// The TypeScript verifier must reproduce testdata/vectors.json, generated by
// the Go node, byte for byte.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { hashStruct, type Hex } from "viem";
import {
  EVENT_TYPES, contentCommit, delegationId, domainSeparator, eventId, eventLeaf, recoverSigner, verifyProof, type SignedEvent,
} from "../src/verify.ts";

const v = JSON.parse(readFileSync(new URL("../../testdata/vectors.json", import.meta.url), "utf8"));
const m = { chainId: v.domain.chainId, registry: v.domain.verifyingContract };
const lower = (h: string) => h.toLowerCase();

test("domain separator", () => {
  assert.equal(lower(domainSeparator(m)), lower(v.domain.separator));
});

for (const ev of v.events) {
  test(`event: ${ev.name}`, async () => {
    const e = ev.signed.event;
    const sh = hashStruct({ data: { ...e, seq: BigInt(e.seq), ts: BigInt(e.ts) }, primaryType: "Event", types: EVENT_TYPES });
    assert.equal(lower(sh), lower(ev.structHash), "structHash");
    const id = eventId(e, m);
    assert.equal(lower(id), lower(ev.eventId), "eventId");
    assert.equal(lower(await recoverSigner(id, ev.signed.sig)), lower(ev.signer), "signer");
    assert.equal(lower(eventLeaf(ev.signed, id, m)), lower(ev.leaf), "leaf");
    if (ev.signed.delegation) {
      const did = delegationId(ev.signed.delegation.delegation, m);
      assert.equal(lower(did), lower(ev.delegationId), "delegation id");
      assert.equal(lower(await recoverSigner(did, ev.signed.delegation.walletSig)), lower(ev.signed.event.author), "delegation issuer");
    }
    if (ev.blob) assert.equal(lower(contentCommit(ev.blob.salt, ev.blob.body)), lower(ev.contentCommit), "content commit");
  });
}

for (const [n, t] of Object.entries<{ leaves: Hex[]; root: Hex; proofs: Hex[][] }>(v.trees)) {
  test(`merkle tree with ${n} leaves`, () => {
    t.leaves.forEach((l, i) => assert.ok(verifyProof(l, t.proofs[i], t.root), `leaf ${i}`));
    const forged = "0x" + "11".repeat(32) as Hex;
    assert.ok(!verifyProof(forged, t.proofs[0], t.root), "forged leaf must not verify");
  });
}

test("tampered event no longer recovers its author", async () => {
  const neg = v.negatives.find((x: { name: string }) => x.name.startsWith("field changed"));
  const se: SignedEvent = neg.signed;
  const who = await recoverSigner(eventId(se.event, m), se.sig);
  assert.notEqual(lower(who), lower(se.event.author));
});

test("high-s signature is rejected", async () => {
  const neg = v.negatives.find((x: { name: string }) => x.name === "high-s signature");
  await assert.rejects(recoverSigner(eventId(neg.signed.event, m), neg.signed.sig), /high s/);
});

test("signature does not verify under another chain id", async () => {
  const se: SignedEvent = v.wrongChainEvent;
  const who = await recoverSigner(eventId(se.event, { ...m, chainId: v.wrongChainId }), se.sig);
  assert.notEqual(lower(who), lower(se.event.author));
});
